import React, { useEffect, useState } from 'react';
import '../styles/home.css';
import { FaHome, FaSearch, FaBell, FaUserFriends, FaPlus, FaUserCircle } from 'react-icons/fa';

const Home = () => {
  const [posts, setPosts] = useState([]);
  const [suggestions, setSuggestions] = useState([]);

  useEffect(() => {
    // Dummy Data
    setPosts([
      { id: 1, user: 'Aman', content: 'Just got placed at Amazon!', likes: 10, comments: 2 },
      { id: 2, user: 'Simran', content: 'Join my DSA bootcamp!', likes: 5, comments: 1 },
    ]);

    setSuggestions([
      { id: 1, name: 'Harpreet Singh', branch: 'CSE' },
      { id: 2, name: 'Mandeep Kaur', branch: 'IT' },
    ]);
  }, []);

  return (
    <div className="insta-home-container">
      {/* Sidebar */}
      <div className="insta-sidebar">
        <h2 className="insta-logo">CampusGram</h2>
        <ul>
          <li><FaHome /> Home</li>
          <li><FaSearch /> Search</li>
          <li><FaUserFriends /> Messages</li>
          <li><FaBell /> Notifications</li>
          <li><FaPlus /> Create</li>
          <li><FaUserCircle /> Profile</li>
        </ul>
      </div>

      {/* Feed */}
      <div className="insta-feed">
        {/* Stories */}
        <div className="insta-stories">
          <div className="story-bubble">You</div>
          <div className="story-bubble">Aman</div>
          <div className="story-bubble">Simran</div>
          <div className="story-bubble">Rohan</div>
        </div>

        {/* Posts */}
        {posts.map(post => (
          <div key={post.id} className="post-card">
            <h4>{post.user}</h4>
            <p>{post.content}</p>
            <div className="post-actions">
              <span>❤️ {post.likes}</span>
              <span>💬 {post.comments}</span>
            </div>
          </div>
        ))}
      </div>

      {/* Right Sidebar */}
      <div className="insta-rightbar">
        <div className="profile-section">
          <img src="https://via.placeholder.com/40" alt="User" />
          <div>
            <strong>kaur_ramgariah01</strong>
            <p>Taranpreet</p>
          </div>
        </div>

        <h4>Suggested for you</h4>
        {suggestions.map(user => (
          <div key={user.id} className="suggestion-card">
            <div>
              <strong>{user.name}</strong>
              <small>{user.branch}</small>
            </div>
            <button>Follow</button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Home;
